// Triple gate: global kill switch + outbound + explicit Journey-F enable in policy.
const rows = $input.all().map(i => i.json).filter(r => r.key);
const cfg = {}; rows.forEach(r => { cfg[r.key] = r.value; });
const policy = JSON.parse($env.FOLLOWUP_POLICY_JSON || '{}');
const outreach = policy.outreach_journey_f || {};
if (cfg.global_ai_enabled !== 'true' || cfg.outbound_enabled !== 'true' || outreach.enabled !== true) {
  console.log(JSON.stringify({ level: 'info', workflow: 'SB-02', action: 'outreach_skipped', reason: outreach.enabled !== true ? 'journey_f_disabled_by_policy' : 'kill_switch', ts: new Date().toISOString() }));
  return [];
}
return [{ json: { cfg, outreach, run_id: 'of_' + Date.now().toString(36) } }];

// Enforces consent source whitelist, consent age, messaging hours and daily cap.
const gate = $('Outreach Enabled Gate').first().json;
const outreach = gate.outreach;
const m = (JSON.parse($env.SF_FIELD_MAP_JSON || '{}').mappings || {});
const fname = (k) => { const s = m[k]; return s && s.field !== 'UNMAPPED' && s.object === 'Lead' ? s.field : null; };
let records = [];
try { records = $('Salesforce: Eligible Consented Leads').first().json.records || []; } catch (e) { records = []; }
const req = outreach.requires || {};
const hours = { timezone: $env.MESSAGING_TIMEZONE || 'America/New_York', start: $env.MESSAGING_HOURS_START || '09:00', end: $env.MESSAGING_HOURS_END || '20:00', days: ['Mon','Tue','Wed','Thu','Fri','Sat'] };
function withinHours(nowISO, h) { const now = new Date(nowISO); const fmt = new Intl.DateTimeFormat('en-US', { timeZone: h.timezone, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit' }); const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value])); const hm = `${parts.hour === '24' ? '00' : parts.hour}:${parts.minute}`; if (h.days && !h.days.includes(parts.weekday)) return false; return hm >= h.start && hm < h.end; }
if (!withinHours(new Date().toISOString(), hours)) { console.log(JSON.stringify({ level: 'info', workflow: 'SB-02', action: 'outreach_skipped', reason: 'outside_messaging_hours', ts: new Date().toISOString() })); return []; }
const cap = Number(outreach.daily_cap || 50);
const out = [];
for (const r of records.slice(0, cap)) {
  const src = fname('consent_source') ? r[fname('consent_source')] : null;
  const ts = fname('consent_timestamp') ? r[fname('consent_timestamp')] : null;
  const allowedSources = req.consent_source_in || [];
  if (allowedSources.length && !allowedSources.includes(src)) continue;
  if (req.consent_max_age_days && (!ts || (Date.now() - new Date(ts).getTime()) > req.consent_max_age_days * 86400000)) continue;
  const phoneRaw = r[fname('mobile_phone')];
  const digits = String(phoneRaw || '').replace(/[^\d+]/g, '');
  const phone = /^\+\d{8,15}$/.test(digits) ? digits : (digits.replace(/\D/g, '').length === 10 ? '+1' + digits.replace(/\D/g, '') : null);
  if (!phone) continue;
  out.push({ json: { record_id: r.Id, record_ref: 'Lead:' + r.Id, phone, first_name: r.FirstName || null, correlation_id: gate.run_id + '_' + r.Id, template_id: outreach.template_id || 'outreach_intro_v1' } });
}
console.log(JSON.stringify({ level: 'info', workflow: 'SB-02', workflow_version: '1.0.0', action: 'outreach_batch', run_id: gate.run_id, eligible: out.length, ts: new Date().toISOString() }));
return out;

// Template comes from compliance-reviewed config only — never model-generated.
const templates = JSON.parse($env.OUTREACH_TEMPLATES_JSON || '{}');
const t = templates[$json.template_id];
if (!t) { console.log(JSON.stringify({ level: 'warn', workflow: 'SB-02', correlation_id: $json.correlation_id, action: 'skipped_no_approved_template', template_id: $json.template_id, ts: new Date().toISOString() })); return []; }
return [{ json: { ...$json, content: t.replace('{name}', $json.first_name ? ' ' + $json.first_name : '') } }];
